export type Occlusion = {depth:number;desiredParallax:number;receiverSource:string;safeMotionRange:{x:number;y:number;lift:number;units:'source-px';proof:'opaque-coverage-chebyshev';unknownPixels:number};occlusionRisk:'identity-sensitive'|'semantic-sensitive'|'low-detail';fill:'none'|{image:string;protectedMask:string;regions:string[];review:string};finalParallax:{x:number;y:number;lift:number;units:'relative-percent-and-css-px'}};
